import { z } from 'zod';

import { EpochMs, RequestId, SessionId, Sha256Hex } from '../ids.js';
import { AlwaysDestination } from './always-destination.js';

/**
 * A permission request (01 W2 `request`). `requestId` and `requestHash` are generated by
 * the agent when the hook fires and echoed in the decision (D7).
 */
export const ApprovalRequest = z.strictObject({
  id: RequestId,
  sessionId: SessionId,
  requestHash: Sha256Hex,
  /** Plain-language label, never raw JSON ("Run a command"). */
  toolLabel: z.string().min(1).max(200),
  toolName: z.string().min(1).max(200),
  /**
   * Folder name of the session's working directory (D21: never the full path). Optional:
   * agents before M1-11 do not send it. It travels only inside the sealed session.
   */
  project: z.string().min(1).max(128).optional(),
  /** What the tool will do (command, path, summary). */
  content: z.string().max(4000),
  /** `true` when `content` was cut; Allow is then disabled on the phone. */
  truncated: z.boolean(),
  suggestions: z.array(z.string().max(200)).max(10),
  /** End of the hold, epoch ms; the phone counts down from here (D10). */
  expiresAt: EpochMs,
  alwaysSupported: z.boolean(),
  /**
   * Where "Always" may store its rules, set by the agent's `always.destinations` (M2-07).
   * Absent: the session only (D24). The phone offers a choice only when it lists more.
   */
  alwaysDestinations: z.array(AlwaysDestination).min(1).max(3).optional(),
});
export type ApprovalRequest = z.infer<typeof ApprovalRequest>;
